def cmd_cli_check_update(args, assoc):
    fmt = assoc.get("format") if isinstance(assoc.get("format"), str) else "table"
    if fmt not in CHECK_UPDATE_FORMATS:
        error("Invalid format: %s. Supported formats are %s."
