    dest = os.path.abspath(os.path.expanduser(dest))
    debug("Extracting '%s' to '%s'" % (archive, dest), "extract")
    try:
        extract(archive, dest)
    except ExtractionError as exc:
        error(str(exc))
    success("Extracted '%s' to '%s'." % (assoc["archive"], dest))


